import re, sys
t = open(r"C:\Users\eric_rash\AppData\Local\Temp\bond.txt", encoding="utf-8").read()
parts = re.split(r"\n=====PAGE (\d+) \(viewer \d+\)=====\n", t)
P = {int(parts[i]): parts[i + 1] for i in range(1, len(parts), 2)}
def norm(s):
    s = s.replace("\u2019", "'").replace("\u2018", "'").replace("\u201c", '"').replace("\u201d", '"')
    return re.sub(r"\s+", " ", s.replace("-\n", "")).lower()
N = {k: norm(v) for k, v in P.items()}
mode = sys.argv[1] if len(sys.argv) > 1 else "q"
if mode == "q":
    for q in open(sys.argv[2], encoding="utf-8").read().strip().split("\n"):
        qq = norm(q)
        hits = [k for k, v in N.items() if qq in v]
        print(f"{hits} :: {q}")
elif mode == "p":
    for a in sys.argv[2:]:
        lo, _, hi = a.partition("-")
        for k in range(int(lo), int(hi or lo) + 1):
            print(f"\n##### PDF page {k} (viewer {k+1}) #####")
            print(re.sub(r"[ \t]+\n", "\n", P[k]))
elif mode == "g":
    pat = re.compile(sys.argv[2], re.I)
    for k, v in N.items():
        for m in pat.finditer(v):
            print(k, "::", v[max(0, m.start() - 150): m.end() + 150])

